export const LP_MONITOR_OUTPUT_MARKER = '__OMNIX_MONITOR_RESULT__';
export const LP_MONITOR_SCHEDULE_INTERVAL_HOURS = 2;
export const LP_MONITOR_ISSUE_PREVIEW_LIMIT = 12;

function shortenAddress(value) {
  const text = String(value || '').trim();
  if (text.length <= 10) return text;
  return `${text.slice(0, 6)}...${text.slice(-4)}`;
}

function resolveChainLabel(issue, chainLabelResolver) {
  const rawChain = String(issue?.chain || '-');
  if (typeof chainLabelResolver !== 'function') {
    return rawChain;
  }
  try {
    return String(chainLabelResolver(rawChain) || rawChain);
  } catch {
    return rawChain;
  }
}

export function parseLpMonitorPayload(output) {
  const line = String(output || '')
    .split('\n')
    .map((item) => item.trim())
    .filter(Boolean)
    .reverse()
    .find((item) => item.includes(LP_MONITOR_OUTPUT_MARKER));

  if (!line) return null;

  const payloadText = line.slice(line.indexOf(LP_MONITOR_OUTPUT_MARKER) + LP_MONITOR_OUTPUT_MARKER.length);
  try {
    const parsed = JSON.parse(payloadText);
    return parsed && Array.isArray(parsed.issues) ? parsed : null;
  } catch {
    return null;
  }
}

export function buildLpMonitorPersistedSummary(params) {
  const {
    payload,
    status,
    triggerType,
    startedAt,
    completedAt,
    notified = false,
    notifyWarning = '',
    error = '',
  } = params;

  return {
    status,
    triggerType,
    startedAt,
    completedAt,
    updatedAt: completedAt,
    scheduledIntervalHours: LP_MONITOR_SCHEDULE_INTERVAL_HOURS,
    owner: payload?.owner || '',
    owners: Array.isArray(payload?.owners) ? payload.owners : [],
    targetCount: Number(payload?.targetCount || 0),
    positionCount: payload?.positionCount || 0,
    checkedCount: payload?.checkedCount || 0,
    issueCount: payload?.issueCount || 0,
    elapsedMs: payload?.elapsedMs || 0,
    chainStats: payload?.chainStats || [],
    issueStats: payload?.issueStats || [],
    runtimeErrors: payload?.runtimeErrors || [],
    issuesPreview: Array.isArray(payload?.issues)
      ? payload.issues.slice(0, LP_MONITOR_ISSUE_PREVIEW_LIMIT)
      : [],
    notified,
    notifyWarning,
    error,
  };
}

export function buildLpMonitorAlertWebhookBody(params) {
  const {
    webhookKind,
    payload,
    chainLabelResolver,
  } = params;

  const shortOwner = shortenAddress(payload.owner);
  const title = `Monitor Alert · ${shortOwner} · ${payload.issueCount} issues`;
  const issueStatText = (payload.issueStats || [])
    .slice(0, 4)
    .map((item) => `${String(item.ruleLabel || item.ruleId || 'rule')}: ${String(item.count || 0)}`)
    .join('  ·  ');

  if (webhookKind === 'custom') {
    return {
      title,
      summary: {
        targetCount: Number(payload.targetCount || 0),
        checkedCount: payload.checkedCount,
        issueCount: payload.issueCount,
        elapsedMs: payload.elapsedMs,
      },
      issues: payload.issues,
    };
  }

  const issueElements = (payload.issues || []).slice(0, 5).flatMap((issue, index) => {
    const ruleLabel = String(issue.ruleLabel || issue.ruleId || 'rule');
    const poolName = String(issue.poolName || issue.poolId || '-');
    const chain = resolveChainLabel(issue, chainLabelResolver);
    const dexName = String(issue.dexName || '-');
    const tokenId = String(issue.tokenId || '-');
    const message = String(issue.message || '-');

    return [
      {
        tag: 'div',
        text: {
          tag: 'lark_md',
          content:
            `**${index + 1}. ${ruleLabel}**\n` +
            `${chain}/${dexName} · ${poolName} · tokenId ${tokenId}\n` +
            `${message}`,
        },
      },
      ...(index < Math.min(payload.issues.length, 5) - 1 ? [{ tag: 'hr' }] : []),
    ];
  });

  return {
    msg_type: 'interactive',
    card: {
      config: {
        wide_screen_mode: true,
        enable_forward: true,
      },
      header: {
        template: payload.issueCount >= 10 ? 'red' : 'orange',
        title: {
          tag: 'plain_text',
          content: title,
        },
      },
      elements: [
        {
          tag: 'div',
          text: {
            tag: 'lark_md',
            content:
              `**${payload.issueCount}** alerts  ·  ` +
              `**${payload.checkedCount}** checked  ·  ` +
              `**${(payload.elapsedMs / 1000).toFixed(2)}s** elapsed`,
          },
        },
        {
          tag: 'div',
          fields: [
            {
              is_short: true,
              text: {
                tag: 'lark_md',
                content: `**Wallet**\n${shortOwner}`,
              },
            },
            {
              is_short: true,
              text: {
                tag: 'lark_md',
                content: `**Triggered Rules**\n${(payload.issueStats || []).length}`,
              },
            },
            {
              is_short: true,
              text: {
                tag: 'lark_md',
                content: `**Contracts**\n${Number(payload.targetCount || 0)}`,
              },
            },
          ],
        },
        ...(issueStatText
          ? [
              {
                tag: 'note',
                elements: [
                  {
                    tag: 'plain_text',
                    content: issueStatText,
                  },
                ],
              },
            ]
          : []),
        { tag: 'hr' },
        ...issueElements,
      ],
    },
  };
}
